/// Check if an IO error represents EOF (e.g. from Ctrl+D).
fn is_eof(e: &io::Error) -> bool {
    e.kind() == io::ErrorKind::UnexpectedEof
}

/// Convert an EOF IO error into a user-friendly interrupted error.
fn handle_eof(e: io::Error) -> BivvyError {
    if is_eof(&e) {
        BivvyError::Io(io::Error::new(io::ErrorKind::Interrupted, "Interrupted (EOF)"))
    } else {
        BivvyError::Io(e)
    }
}

/// Convert dialoguer errors to BivvyError, handling EOF gracefully.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    let io_err: io::Error = e.into();
    handle_eof(io_err)
}

