    fn eof_error_is_detected() {
        let eof = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
        assert!(is_eof(&eof));

        let other = std::io::Error::new(std::io::ErrorKind::Other, "something else");
        assert!(!is_eof(&other));
    }

    #[test]
    fn eof_converted_to_interrupted_error() {
        let eof = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
        let err = handle_eof(eof);
        let msg = err.to_string();
        assert!(msg.contains("nterrupt"), "expected 'Interrupted' in: {}", msg);
    }
}

