    fn is_yes_no_returns_false_for_more_than_two() {
        let options = vec![
            PromptOption {
                label: "Yes".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Maybe".to_string(),
                value: "maybe".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

    #[test]
    fn select_theme_creates_without_panic() {
        let theme = select_theme();
        // Verify the theme object can be used (smoke test)
        drop(theme);
    }

    #[test]
    fn eof_error_is_detected() {
        let eof = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
        assert!(is_eof(&eof));

        let other = std::io::Error::new(std::io::ErrorKind::Other, "something else");
        assert!(!is_eof(&other));
    }

    #[test]
    fn eof_converted_to_interrupted_error() {
        let eof = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
        let err = handle_eof(eof);
        let msg = err.to_string();
        assert!(msg.contains("nterrupt"), "expected 'Interrupted' in: {}", msg);
    }
}

