fn handle_eof(e: io::Error) -> BivvyError {
    if is_eof(&e) {
        BivvyError::Io(io::Error::new(
            io::ErrorKind::Interrupted,
            "Interrupted (EOF)",
        ))
    } else {
        BivvyError::Io(e)
    }
}

