    #[test]
    fn eof_error_is_detected() {
        let eof = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
        assert!(is_eof(&eof));

        let other = std::io::Error::new(std::io::ErrorKind::Other, "something else");
        assert!(!is_eof(&other));
    }

