    fn eof_converted_to_interrupted_error() {
        let eof = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
        let err = handle_eof(eof);
        let msg = err.to_string();
        assert!(
            msg.contains("nterrupt"),
            "expected 'Interrupted' in: {}",
            msg
        );
    }
}

